        debug_assert!(n <= a.len(), "n must not exceed the length of the array");
        debug_assert!(n < 1000, "n must be strictly less than 1000");

        // Initialize the maximum with the first element.
        let mut current_max = a[0];

        // Iterate i = 1 .. n, updating current_max.
        // We give it an invariant that exactly captures
        //   1) current_max ≥ every a[j] for j < i
        //   2) there is some j < i with a[j] == current_max
